// MIT. Complete original municipal request and work-order source editions.
import { canonical, copy, digest, fail, object, text, instant, parseJson, now, entityId, seal, MAX_SOURCE_BYTES, MAX_ROWS } from '../gis/shared.mjs';

import { csvDecode } from './csv.mjs';

export const SOURCE_SCHEMA='commons.open311.follow-through-source.v1';
const RETAINED_SCHEMA='commons.arcgis.retained-source.v1';
function validTime(value,name){return value===undefined||value===null?null:instant(value,name);}
function originalFile(name,originalText,kind,sourceUrl=null,observedAt=null,id=null){
  return {id:id??entityId('file',{name,sha256:digest(originalText)}),name,kind,bytes:Buffer.byteLength(originalText),sha256:digest(originalText),sourceUrl,observedAt};
}
function decode(raw){
  object(raw,'Original capture bytes');
  if(raw.encoding!=='base64'||raw.complete!==true||typeof raw.body!=='string')fail('COMPLETE_CAPTURE_REQUIRED','Each retained capture must contain its complete original base64 body.');
  const bytes=Buffer.from(raw.body,'base64');
  if(bytes.toString('base64')!==raw.body||bytes.length!==raw.bytes||digest(bytes)!==raw.sha256)fail('ORIGINAL_CAPTURE_MISMATCH','The retained original capture bytes or SHA-256 do not match.');
  try{return new TextDecoder('utf-8',{fatal:true,ignoreBOM:true}).decode(bytes);}catch{fail('INVALID_UTF8','The original source body is not valid UTF-8.');}
}
function captureTime(value){if(typeof value!=='string')return null;const iso=value.replace(/^(\d{4}-\d{2}-\d{2}) (\d{2}:\d{2}:\d{2}) UTC$/,'$1T$2Z');return /T.*(?:Z|[+-]\d{2}:\d{2})$/.test(iso)&&Number.isFinite(Date.parse(iso))?iso:null;}
function fieldsFor(value,metadata){
  const explicit=value.fields??metadata?.fields;
  const map=new Map((Array.isArray(explicit)?explicit:[]).filter(f=>f&&typeof f.name==='string').map(f=>[f.name,{...copy(f),name:f.name,type:f.type??'unknown',alias:f.alias??f.name}]));
  for(const feature of value.features??[]){const attributes=feature?.attributes??feature?.properties??{};for(const [name,item]of Object.entries(attributes)){if(!map.has(name))map.set(name,{name,type:item===null?'unknown':Array.isArray(item)?'array':typeof item,alias:name});}}
  return [...map.values()];
}
function inferKind(value){
  if(value?.error)return 'arcgis';
  if(value?.type==='FeatureCollection'&&Array.isArray(value.features))return 'geojson';
  if(Array.isArray(value?.features))return 'arcgis';
  if(Array.isArray(value))return 'records';
  if(Array.isArray(value?.records))return 'records';
  if(value?.schema==='commons.open311.collection-export.v1')return 'open311-collection';
  if(value?.schema==='commons.open311.service-report.v1')return 'open311-report';
  fail('UNSUPPORTED_SOURCE','Choose a complete ArcGIS feature response, GeoJSON FeatureCollection, row array, Open311 collection or service report.');
}
function features(value,kind){
  if(kind==='records'||kind==='csv')return (Array.isArray(value)?value:value.records).map(attributes=>({attributes}));
  if(kind==='open311-collection'){
    const rows=value.rows??value.items??value.requests;
    if(!Array.isArray(rows))fail('COLLECTION_ROWS_REQUIRED','The complete collection export must contain its consolidated rows.');
    return rows.map(row=>({attributes:copy(row.source??row),geometry:row.longitude!==null&&row.latitude!==null&&Number.isFinite(row.longitude)&&Number.isFinite(row.latitude)?{x:row.longitude,y:row.latitude,spatialReference:{wkid:4326}}:null,open311:copy(row)}));
  }
  if(kind==='open311-report'){
    if(!Array.isArray(value.rows))fail('REPORT_ROWS_REQUIRED','The complete service report must contain its rows.');
    return value.rows.map(row=>({attributes:copy(row.source??row),geometry:row.source?.long!==null&&row.source?.lat!==null&&Number.isFinite(Number(row.source?.long))&&Number.isFinite(Number(row.source?.lat))?{x:Number(row.source.long),y:Number(row.source.lat),spatialReference:{wkid:4326}}:null,open311:copy(row)}));
  }
  return value.features??[];
}
function sourceError(value){return value?.error?{code:value.error.code??'SOURCE_ERROR',message:String(value.error.message??'The original source returned an error.'),details:copy(value.error.details??null)}:null;}
function parseSelected(originalText,options={}){
  if(typeof originalText!=='string'||Buffer.byteLength(originalText)>MAX_SOURCE_BYTES)fail('SOURCE_SIZE','Use one complete original source input of at most 128 MiB.',413);
  const csv=options.kind==='csv'||(!options.kind||options.kind==='auto')&&/\.csv$/i.test(options.name??'');
  const root=csv?csvDecode(originalText):parseJson(originalText,'Original municipal source'),files=[originalFile(options.name??'original-source.json',originalText,root?.schema===RETAINED_SCHEMA?'retained-packet':'source',options.sourceUrl??null,options.observedAt??null)];
  let selected=[],metadata=options.metadataText===undefined?null:parseJson(options.metadataText,'Original layer metadata'),availableCaptures=[];
  if(options.metadataText!==undefined){if(Buffer.byteLength(options.metadataText)>MAX_SOURCE_BYTES)fail('METADATA_SIZE','The original layer metadata exceeds 128 MiB.',413);files.push(originalFile('original-layer-metadata.json',options.metadataText,'metadata',null,null));}
  if(root.schema===RETAINED_SCHEMA){
    if(!Array.isArray(root.captures)||!root.captures.length)fail('CAPTURE_REQUIRED','The retained source packet has no original captures.');
    const decoded=root.captures.map(c=>{text(c.id,'Capture identity',200);const body=decode(c.raw),value=parseJson(body,'Original capture');return {capture:c,body,value};});
    if(new Set(decoded.map(c=>c.capture.id)).size!==decoded.length)fail('DUPLICATE_CAPTURE','The retained packet repeats a capture ID.');
    availableCaptures=decoded.filter(c=>Array.isArray(c.value?.features)||c.value?.error).map(c=>({id:c.capture.id,state:sourceError(c.value)?'source_error':'ready',rows:Array.isArray(c.value.features)?c.value.features.length:0,sourceUrl:c.capture.receipt?.url??null}));
    let ids=options.captureIds;
    if(ids===undefined){const ready=availableCaptures.filter(c=>c.state==='ready');if(ready.length===1)ids=[ready[0].id];else if(availableCaptures.length===1)ids=[availableCaptures[0].id];else return {root,files,metadata,selected:[],availableCaptures,selectionRequired:true};}
    if(!Array.isArray(ids)||!ids.length||ids.some(id=>typeof id!=='string')||new Set(ids).size!==ids.length)fail('CAPTURE_SELECTION_REQUIRED','Select distinct complete original capture IDs.');
    selected=ids.map(id=>{const found=decoded.find(c=>c.capture.id===id);if(!found)fail('CAPTURE_NOT_FOUND','An original selected capture was not found.',404,{id});return found;});
    if(!metadata){
      const target=selected[0].capture.receipt?.url??'',layerId=target.match(/\/(?:MapServer|FeatureServer)\/(\d+)(?:\/query)?(?:\?|$)/i)?.[1];
      const all=decoded.flatMap(c=>[...(c.value.layers??[]),...(c.value.tables??[])]).filter(x=>Array.isArray(x.fields));
      metadata=layerId!==undefined?all.find(x=>String(x.id)===layerId)??null:null;
      if(!metadata)metadata=decoded.map(c=>c.value).find(x=>Array.isArray(x.fields)&&!Array.isArray(x.features))??null;
    }
    for(const item of decoded)files.push(originalFile(item.capture.receipt?.provenance?.originalFilename??item.capture.id+'.json',item.body,item.capture.role??'capture',item.capture.receipt?.url??null,captureTime(item.capture.receipt?.observedAt),item.capture.id));
  }else selected=[{body:originalText,value:root,capture:{id:files[0].id,receipt:{url:options.sourceUrl??null,observedAt:options.observedAt??null}}}];
  return {root,files,metadata,selected,availableCaptures,selectionRequired:false};
}
export function inspectSource(originalText,options={}){
  const parsed=parseSelected(originalText,options),{selected,metadata}=parsed;
  if(parsed.selectionRequired)return {name:options.name??'Original source',kind:'arcgis-retained',role:options.role??null,state:'selection_required',rows:0,fields:[],spatialReference:null,coverage:{selectionRequired:true},originalFiles:parsed.files,error:null,availableCaptures:parsed.availableCaptures};
  let rows=0;const fieldMap=new Map(),pages=[],errors=[],kinds=new Set();
  for(const item of selected){
    const error=sourceError(item.value),kind=options.kind==='csv'||(!options.kind||options.kind==='auto')&&/\.csv$/i.test(options.name??'')?'csv':inferKind(item.value);kinds.add(kind);
    const list=error?[]:features(item.value,kind);if(!Array.isArray(list))fail('SOURCE_ROWS_REQUIRED','The original source rows must be an array.');
    rows+=list.length;if(rows>MAX_ROWS)fail('SOURCE_ROWS_LIMIT','One source edition can contain at most 100,000 original rows.',413);
    const effective={...item.value,features:list};for(const field of fieldsFor(effective,metadata))fieldMap.set(field.name,field);
    if(error)errors.push({captureId:item.capture.id,...error});
    let query={};try{query=Object.fromEntries(new URL(item.capture.receipt?.url??options.sourceUrl).searchParams);}catch{}
    pages.push({captureId:item.capture.id,rows:list.length,sha256:digest(item.body),sourceUrl:item.capture.receipt?.url??options.sourceUrl??null,observedAt:captureTime(item.capture.receipt?.observedAt),query,
      exceededTransferLimit:item.value.exceededTransferLimit??null,terminal:kind==='arcgis'&&!error?item.value.exceededTransferLimit!==true:null,state:error?'source_error':'ready'});
  }
  if(kinds.size>1)fail('SOURCE_KIND_MISMATCH','Select original pages of one source format.');
  const first=selected[0],kind=[...kinds][0],spatialReference=copy(first.value.spatialReference??(kind==='geojson'?{wkid:4326,source:'RFC7946'}:metadata?.spatialReference??null));
  return {name:options.name??metadata?.name??'Original source',kind,role:options.role??null,state:errors.length?'source_error':'ready',rows,fields:[...fieldMap.values()],spatialReference,
    coverage:{scope:'Selected complete original files',pages,selectedCaptures:selected.map(c=>c.capture.id),hasSaturatedPage:pages.some(p=>p.exceededTransferLimit===true),terminal:pages.length?pages.at(-1).terminal:null,declaredMaxRecordCount:metadata?.maxRecordCount??null,sourcePopulation:'Only records returned by the saved original query or file are represented.'},
    originalFiles:parsed.files,error:errors[0]??null,errors,availableCaptures:parsed.availableCaptures,metadata:metadata?copy(metadata):null};
}
export function importSource(originalText,options={},identity={}){
  text(options.role,'Source role',20);if(!['requests','orders'].includes(options.role))fail('INVALID_SOURCE_ROLE','Source role must be requests or orders.');
  text(options.seriesId,'Source series ID',200);text(options.name??'Original source','Source name',300);
  instant(options.observedAt,'Source observation time');
  const inspected=inspectSource(originalText,options);if(inspected.state==='selection_required')fail('CAPTURE_SELECTION_REQUIRED','Select the original dataset captures before importing.',400,{availableCaptures:inspected.availableCaptures});
  const savedOptions={role:options.role,seriesId:options.seriesId,name:options.name??inspected.name,observedAt:options.observedAt};
  for(const key of ['sourceUrl','metadataText','captureIds','kind'])if(options[key]!==undefined)savedOptions[key]=copy(options[key]);
  const sourceId=entityId('source',{originalSha256:digest(originalText),options:savedOptions});
  return seal({schema:SOURCE_SCHEMA,id:sourceId,...inspected,name:savedOptions.name,seriesId:options.seriesId,role:options.role,observedAt:options.observedAt,createdAt:identity.createdAt??now(),options:savedOptions,originalText});
}
export function sourceSummary(source){const {id,name,seriesId,kind,role,observedAt,rows,sha256,coverage,createdAt,state}=source;return {id,name,seriesId,kind,role,observedAt,rows,sha256,coverage,createdAt,state};}
export function sourceDetail(source){const {originalText,options,metadata,...view}=source;return {...copy(view),metadata:metadata?copy(metadata):null};}
export function originalRows(source){
  const parsed=parseSelected(source.originalText,source.options),rows=[];let index=0;
  for(const item of parsed.selected){
    if(sourceError(item.value))continue;
    const kind=source.kind,sr=item.value.spatialReference??(kind==='geojson'?{wkid:4326,source:'RFC7946'}:parsed.metadata?.spatialReference??null);
    for(const raw of features(item.value,kind)){
      object(raw,'Original source record');
      const attributes=kind==='geojson'?(raw.properties??{}):(raw.attributes??raw.properties??{});object(attributes,'Original attributes');
      const geometry=raw.geometry??null,spatialReference=geometry?.spatialReference??sr;
      rows.push({index:index++,captureId:item.capture.id,attributes:copy(attributes),geometry:copy(geometry),spatialReference:copy(spatialReference),sourceSha256:digest(raw),original:copy(raw)});
    }
  }
  return rows;
}
export function sourceOriginalFile(source,fileId){
  if(fileId===undefined||fileId===null||fileId===source.originalFiles[0].id)return {filename:source.originalFiles[0].name,body:source.originalText};
  if(fileId===source.originalFiles.find(f=>f.kind==='metadata')?.id&&source.options.metadataText!==undefined)return {filename:'original-layer-metadata.json',body:source.options.metadataText};
  const parsed=source.kind==='csv'?null:parseJson(source.originalText);
  const capture=parsed?.schema===RETAINED_SCHEMA?parsed.captures.find(c=>c.id===fileId):null;
  if(!capture)fail('SOURCE_FILE_NOT_FOUND','The selected complete original source file was not found.',404);
  return {filename:source.originalFiles.find(f=>f.id===fileId)?.name??fileId+'.json',body:decode(capture.raw)};
}

// MIT. Source-linked municipal service and work-order follow-through.
import { canonical, copy, digest, fail, object, text, instant, equal, entityId, seal, verifySeal, uniqueStrings, parseJson } from '../gis/shared.mjs';
import { originalRows } from './source.mjs';

export const PROFILE_SCHEMA='commons.open311.follow-through-profile.v1';
export const EDITION_SCHEMA='commons.open311.follow-through-edition.v1';
export const LINK_SCHEMA='commons.open311.follow-through-link.v1';
export const WORK_SCHEMA='commons.open311.follow-through-work.v1';
export const REVIEW_SCHEMA='commons.open311.follow-through-review.v1';
export const RETURN_SCHEMA='commons.open311.follow-through-return.v1';
export const DECISION_SCHEMA='commons.open311.follow-through-decision.v1';
export const DISPATCH_SCHEMA='commons.open311.follow-through-dispatch.v1';
export const WORK_STATUSES=['new','assigned','in_progress','done','dismissed'];
export const ACTIONS=['review','contact','inspect','create_work_order','update_work_order','reconcile','none'];
const PRIORITIES=['low','normal','high','urgent'],APPROVALS=['draft','approved','rejected'];
const nullField=value=>value===undefined||value===null||value===''?null:text(value,'Field name',200);
function choice(value,allowed,name){if(!allowed.includes(value))fail('INVALID_CHOICE',name+' must be one of '+allowed.join(', ')+'.');return value;}
function strings(value,name){return uniqueStrings(value??[],name,{max:1000});}
function values(value,name){if(!Array.isArray(value))fail('INVALID_VALUES',name+' must be an array of original JSON values.');return copy(value);}
function scalar(value){return value===null||['string','number','boolean'].includes(typeof value);}
function originalString(value){return value===null||value===undefined?'':typeof value==='string'?value:canonical(value);}
function coordinates(input={}){
  object(input,'Coordinate interpretation');const mode=choice(input.mode??'source',['source','wgs84','web-mercator','manual'],'Coordinate interpretation');
  const name=text(input.name??'','Interpretation name',300,{empty:true}),sourceReferences=strings(input.sourceReferences??[],'Interpretation references');
  if(mode!=='source'&&(!name.trim()||!sourceReferences.length))fail('COORDINATE_REFERENCE_REQUIRED','A coordinate interpretation needs a name and its operator or source reference.');
  const result={mode,name,sourceReferences};
  if(mode==='manual'){
    if(!validLonLat(input.longitude,input.latitude))fail('INVALID_COORDINATES','Manual location requires numeric longitude −180…180 and latitude −90…90.');
    result.longitude=input.longitude;result.latitude=input.latitude;
  }else if(input.longitude!==undefined||input.latitude!==undefined){result.longitude=null;result.latitude=null;}
  return result;
}
function roleProfile(input,name){
  object(input,name+' mapping');const idFields=uniqueStrings(input.idFields??[],name+' identity fields',{empty:name==='Order',max:16});
  const dates={};for(const [key,mapping]of Object.entries(input.dates??{})){
    if(!['createdAt','updatedAt','closedAt'].includes(key))fail('INVALID_DATE_MAPPING','Date mappings use createdAt, updatedAt or closedAt.');
    object(mapping,'Date field mapping');dates[key]={field:text(mapping.field,'Date field',200),format:choice(mapping.format,['epoch-ms','iso-offset','literal'],'Date format')};
  }
  const result={idFields,titleField:nullField(input.titleField),descriptionField:nullField(input.descriptionField),statusField:nullField(input.statusField),referenceFields:strings(input.referenceFields,name+' reference fields'),dates,coordinates:coordinates(input.coordinates??{})};
  if(name==='Request'){
    const need=input.workNeeded??{};result.workNeeded={field:nullField(need.field),neededValues:values(need.neededValues??[],'Work required values'),notNeededValues:values(need.notNeededValues??[],'Work not required values')};
    if(result.workNeeded.neededValues.some(v=>result.workNeeded.notNeededValues.some(w=>equal(v,w))))fail('WORK_NEEDED_MAPPING_CONFLICT','A source value cannot mean both work required and work not required.');
  }else result.costs=(input.costs??[]).map(item=>{object(item,'Order cost mapping');return {field:text(item.field,'Cost field',200),label:text(item.label??item.field,'Cost label',200),unit:item.unit===undefined||item.unit===null?null:text(item.unit,'Cost unit',100)};});
  if(result.coordinates.mode==='manual')fail('PROFILE_MANUAL_LOCATION','A manual point belongs to one source record; profile coordinate mappings apply to a complete role.');
  return result;
}
export function normalizeProfile(input){
  object(input,'Follow-through profile');text(input.id,'Profile ID',100);text(input.name,'Profile name',300);
  if(!Number.isSafeInteger(input.revision)||input.revision<1)fail('PROFILE_REVISION_REQUIRED','A profile revision is a positive integer.');
  const request=roleProfile(input.request,'Request'),order=roleProfile(input.order??{idFields:['WORKORDERID']},'Order');
  const joins=(input.joins??[]).map(join=>{object(join,'Relationship mapping');return {id:text(join.id,'Relationship rule ID',100),name:text(join.name,'Relationship name',300),requestField:text(join.requestField,'Request relationship field',200),orderField:text(join.orderField,'Order relationship field',200),normalization:choice(join.normalization??'exact',['exact','trim-text','fold-text'],'Relationship value normalization')};});
  if(new Set(joins.map(j=>j.id)).size!==joins.length)fail('DUPLICATE_JOIN_ID','Relationship rule IDs must be distinct.');
  const statuses={};for(const key of ['requestClosed','requestActive','orderClosed','orderActive'])statuses[key]=values(input.statuses?.[key]??[],key);
  for(const role of ['request','order'])if(statuses[role+'Closed'].some(v=>statuses[role+'Active'].some(w=>equal(v,w))))fail('STATUS_MAPPING_CONFLICT','An original '+role+' status cannot mean both active and closed.');
  const r=input.rules??{},rules={requireOrderWhenNeeded:r.requireOrderWhenNeeded??true,flagMultipleCandidates:r.flagMultipleCandidates??true,flagRequestClosedOrderActive:r.flagRequestClosedOrderActive??true,flagOrderClosedRequestActive:r.flagOrderClosedRequestActive??true,staleAfterDays:r.staleAfterDays??null};
  for(const key of Object.keys(rules).filter(k=>k!=='staleAfterDays'))if(typeof rules[key]!=='boolean')fail('INVALID_RULE',key+' must be true or false.');
  if(rules.staleAfterDays!==null&&(!Number.isFinite(rules.staleAfterDays)||rules.staleAfterDays<0))fail('INVALID_STALENESS','Stale-after days must be nonnegative or null.');
  return seal({schema:PROFILE_SCHEMA,id:input.id,key:input.id+'@'+input.revision,name:input.name,revision:input.revision,request,order,joins,statuses,rules,notes:text(input.notes??'','Profile notes',100000,{empty:true})});
}
export function validLonLat(x,y){return typeof x==='number'&&Number.isFinite(x)&&x>=-180&&x<=180&&typeof y==='number'&&Number.isFinite(y)&&y>=-90&&y<=90;}
function point(raw){
  const geometry=raw.geometry;if(!geometry)return null;
  if(geometry.type==='Point'&&Array.isArray(geometry.coordinates))return {x:geometry.coordinates[0],y:geometry.coordinates[1]};
  return Object.hasOwn(geometry,'x')&&Object.hasOwn(geometry,'y')?{x:geometry.x,y:geometry.y}:null;
}
export function coordinateFingerprint(row){return digest({geometry:row.originalGeometry??null,spatialReference:row.spatialReference??null});}
export function locate(row,interpretation={mode:'source',name:'',sourceReferences:[]}){
  const value=coordinates(interpretation),raw=point({geometry:row.originalGeometry??row.geometry}),sr=row.spatialReference??row.originalGeometry?.spatialReference??null;
  let x=null,y=null,reason=null;
  if(value.mode==='manual'){x=value.longitude;y=value.latitude;}
  else if(!raw)reason='The original record has no point geometry.';
  else if(typeof raw.x!=='number'||typeof raw.y!=='number'||!Number.isFinite(raw.x)||!Number.isFinite(raw.y))reason='The original point has nonnumeric or nonfinite coordinates.';
  else if(value.mode==='web-mercator'){
    const max=20037508.342789244;
    if(Math.abs(raw.x)>max||Math.abs(raw.y)>max)reason='The point is outside the configured Web Mercator bounds.';
    else{x=raw.x/6378137*180/Math.PI;y=(2*Math.atan(Math.exp(raw.y/6378137))-Math.PI/2)*180/Math.PI;}
  }else if(value.mode==='wgs84'){x=raw.x;y=raw.y;}
  else if([4326].includes(sr?.latestWkid??sr?.wkid)||sr?.source==='RFC7946'){x=raw.x;y=raw.y;}
  else reason='The original reference is not a declared WGS84 point. Choose a named interpretation.';
  if(reason===null&&!validLonLat(x,y))reason='The original coordinates do not fit WGS84 longitude and latitude bounds.';
  return {geometry:reason===null?{type:'Point',coordinates:[x,y]}:null,interpretation:copy(value),coordinateSha256:coordinateFingerprint(row),reason};
}
function mappedDate(attributes,mapping){
  const sourceValue=Object.hasOwn(attributes,mapping.field)?copy(attributes[mapping.field]):null;let parsed=null;
  if(sourceValue!==null&&sourceValue!==''&&mapping.format!=='literal'){
    if(mapping.format==='epoch-ms'){const numeric=typeof sourceValue==='number'?sourceValue:typeof sourceValue==='string'&&/^[+-]?\d+(?:\.\d+)?$/.test(sourceValue)?Number(sourceValue):null;if(numeric!==null&&Number.isFinite(numeric)&&Math.abs(numeric)<=8640000000000000)parsed=new Date(numeric).toISOString();}
    if(mapping.format==='iso-offset'&&typeof sourceValue==='string'&&/T.*(?:Z|[+-]\d{2}:\d{2})$/.test(sourceValue)&&Number.isFinite(Date.parse(sourceValue)))parsed=new Date(sourceValue).toISOString();
  }
  return {field:mapping.field,format:mapping.format,sourceValue,instant:parsed};
}
function hasOriginal(values,value){return values.some(v=>equal(v,value));}
function normalizedRows(source,mapping,role){
  if(source.state!=='ready')fail('SOURCE_ERROR_SELECTED','Choose a successful original dataset; this source retains an error response.',400,{sourceId:source.id,error:source.error});
  const grouped=new Map();
  for(const raw of originalRows(source)){
    const attributes=raw.attributes,identityValues=mapping.idFields.map(field=>Object.hasOwn(attributes,field)?attributes[field]:null),identityValid=identityValues.every(value=>scalar(value)&&value!==null&&value!=='');
    const key=entityId(role,identityValid?{seriesId:source.seriesId,idFields:mapping.idFields,values:identityValues}:{sourceId:source.id,index:raw.index,sourceSha256:raw.sourceSha256});
    const dates=Object.fromEntries(Object.entries(mapping.dates).map(([name,date])=>[name,mappedDate(attributes,date)]));
    const locationBase={originalGeometry:raw.geometry,spatialReference:raw.spatialReference},location=locate(locationBase,mapping.coordinates);
    const issues=[];
    if(!identityValid)issues.push({code:'MISSING_SOURCE_ID',label:'Missing mapped source identity',detail:'One or more selected business identity fields are null, empty or not scalar.'});
    for(const [name,date]of Object.entries(dates))if(date.sourceValue!==null&&date.sourceValue!==''&&date.format!=='literal'&&date.instant===null)issues.push({code:'INVALID_SOURCE_DATE',label:'Unparsed '+name,detail:'The source value in '+date.field+' does not match '+date.format+'.'});
    if(location.geometry===null)issues.push({code:'UNLOCATED_SOURCE',label:'Location needs interpretation',detail:location.reason});
    const common={key,sourceSha256:raw.sourceSha256,sourceId:source.id,sourceSeriesId:source.seriesId,captureId:raw.captureId,sourceIndex:raw.index,identityValues:copy(identityValues),identityValid,
      title:originalString(mapping.titleField?attributes[mapping.titleField]:identityValues.length===1?identityValues[0]:identityValues),
      description:originalString(mapping.descriptionField?attributes[mapping.descriptionField]:null),
